import {BALANCE as B,ZOMBIES} from './data.js';
export const BOSSES={crusher:{id:'crusher',name:'THE CRUSHER',hp:4200,speed:.28,damage:150,attackInterval:1.35,color:'#66755b',threatCost:18,ability:'CHARGE ATTACK',chargeCooldown:9,telegraph:1.8,chargeSpeed:4.2},collector:{id:'collector',name:'THE COLLECTOR',hp:4100,speed:.34,damage:90,attackInterval:1.05,color:'#786a49',threatCost:16,ability:'SUN THIEF',structural:true},foreman:{id:'foreman',name:'THE FOREMAN',hp:3700,speed:.33,damage:80,attackInterval:1.05,color:'#596d66',threatCost:15,ability:'COMMAND AURA',structural:true}};
export const isBossWave=n=>n>0&&n%B.bossEvery===0;
export function threatBudget(n){return isBossWave(n)?Math.round(14+n*1.5):Math.round(B.waves.baseBudget+(n-1)*B.waves.budgetGrowth+Math.floor((n-1)/10)*B.waves.chapterGrowth)}
function available(n){return ZOMBIES.filter(z=>z.id==='normal'||(z.id==='conehead'&&n>=3)||(z.id==='buckethead'&&n>=5))}
function compositionFor(n,budget,rng){const counts=Object.fromEntries(ZOMBIES.map(z=>[z.id,0]));let left=budget,guard=200,pool=available(n);while(left>=1&&guard--){const a=pool.filter(z=>z.threatCost<=left+.001);if(!a.length)break;const weights=a.map(z=>z.id==='normal'?6:z.id==='conehead'?4:2),total=weights.reduce((x,y)=>x+y,0);let roll=rng()*total,z=a[0];for(let i=0;i<a.length;i++){roll-=weights[i];if(roll<0){z=a[i];break}}counts[z.id]++;left-=z.threatCost}return ZOMBIES.filter(z=>counts[z.id]).map(z=>({type:z.id,name:z.name,count:counts[z.id],threatCost:z.threatCost}))}
function makeGroups(enemies,rng,bossId=null){const bag=[];for(const e of enemies)for(let i=0;i<e.count;i++)bag.push(e.type);for(let i=bag.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[bag[i],bag[j]]=[bag[j],bag[i]]}const groups=[];if(bossId)groups.push({enemies:[{type:'boss',bossId,count:1}],insideDelay:0,afterDelay:2.8});let at=0;while(at<bag.length){const size=Math.min(bag.length-at,2+Math.floor(rng()*4));const slice=bag.slice(at,at+size),packed=[];for(const type of slice){const p=packed.find(x=>x.type===type);p?p.count++:packed.push({type,count:1})}groups.push({enemies:packed,insideDelay:B.waves.insideDelay,afterDelay:B.waves.groupDelay});at+=size}return groups}
export function createWavePlan(waveNumber,spawnEdges=['north'],rng=Math.random){const type=isBossWave(waveNumber)?'boss':'normal',budget=threatBudget(waveNumber),bossId=type==='boss'?'crusher':null,escortBudget=type==='boss'?Math.max(6,Math.round(budget*.45)):budget,enemies=compositionFor(waveNumber,escortBudget,rng),edges=[...new Set(spawnEdges.length?spawnEdges:['north'])];return {waveNumber,type,bossId,boss:bossId?BOSSES[bossId]:null,enemies,spawnEdges:edges,spawnGroups:makeGroups(enemies,rng,bossId),threatBudget:budget,spentThreat:enemies.reduce((n,e)=>n+e.count*e.threatCost,0)+(bossId?BOSSES[bossId].threatCost:0)}}
export function flattenGroups(plan){const out=[];for(const group of plan.spawnGroups){const flat=[];for(const item of group.enemies)for(let i=0;i<item.count;i++)flat.push({...item});for(let i=0;i<flat.length;i++)out.push({...flat[i],delay:i===flat.length-1?group.afterDelay:group.insideDelay})}return out}
